ansible/roles/monitoring/tasks/main.json:
[
  {
    "ansible.builtin.package": {
      "name": [
        "docker.io",
        "docker-compose"
      ],
      "state": "present",
      "update_cache": true
    },
    "name": "Install monitoring engine"
  },
  {
    "ansible.builtin.systemd": {
      "enabled": true,
      "name": "docker",
      "state": "started"
    },
    "name": "Keep container engine running"
  },
  {
    "ansible.builtin.copy": {
      "dest": "/opt/bromigos-monitoring/",
      "directory_mode": "0755",
      "mode": "0644",
      "src": "{{ playbook_dir }}/../../monitoring/"
    },
    "name": "Copy reviewed monitoring settings",
    "register": "monitoring_files"
  },
  {
    "ansible.builtin.file": {
      "mode": "0755",
      "path": "/opt/bromigos-monitoring/textfile",
      "state": "directory"
    },
    "name": "Create exporter textfile folder"
  },
  {
    "ansible.builtin.shell": {
      "chdir": "/opt/bromigos-monitoring",
      "cmd": "if docker compose version >/dev/null 2>&1; then docker compose -p bromigos-monitoring up -d {{ \"--force-recreate\" if monitoring_files.changed else \"\" }}; else docker-compose -p bromigos-monitoring up -d {{ \"--force-recreate\" if monitoring_files.changed else \"\" }}; fi"
    },
    "changed_when": false,
    "name": "Start monitoring without removing state"
  }
]

